function digits(s) { return String(s || '').replace(/\D/g, ''); }
// MEMBER DATA PROTECTION (docs/key-integration/MEMBER_DATA_PLAN.md): the phone number and the personal-link token are also kept in a hidden spot
// that cannot be listed (lvr_member_private/<token>); referral codes are looked up one at a time (lvr_refcodes/<code>); a hashed index
// (lvr_member_idx/<sha256>) answers "is this the same person" without exposing anyone's phone. Until the owner switches settings/privateLayout on,
// the old public fields are written too, so nothing that works today stops working.
var DB_ROOT = RTDB_URL.replace(/\/lvr_rewards\.json$/, '');
function sha256hex(str) {
  try {
    return crypto.subtle.digest('SHA-256', new TextEncoder().encode(str)).then(function(b){
      return Array.prototype.map.call(new Uint8Array(b), function(x){ return x.toString(16).padStart(2, '0'); }).join('');
    });
  } catch (e) { return Promise.resolve(null); }
}
function idHashes(phone) {
  var d = digits(phone);
  return Promise.all(d.length >= 7 ? [sha256hex('p:' + d)] : []).then(function(a){ return a.filter(Boolean); });
}

